// generar_275_alimentacion_franjas_y_especial.js
// CHIQUI Entre Señales — Franjas de alimentación + alimentación especial
//
// IMPORTANTE: primero corre sql_275_alimentacion.sql en Supabase
// (New snippet) — agrega las columnas alimento_franjas y
// alimentacion_especial a registros_diarios.
//
// 1) 🥘 "ALIMENTÉ A MI MASCOTA" → al marcarlo se abre un mini-modal
//    "¿En qué momento?" con ☀️ Mañana · 🌤️ Tarde · 🌙 Noche
//    (multi-selección). Pensado para cotutores: uno marca la mañana,
//    otro la noche, y así se responde "¿ya le dieron de comer?".
//    Las franjas se guardan como texto coma-separado.
//
// 2) 🍚 "ALIMENTACIÓN ESPECIAL" → botón nuevo en el grupo Alimentación.
//    Al marcarlo, mini-modal con el tipo de dieta:
//      🍲 Dieta blanda · 🩹 Alimento gastrointestinal ·
//      💪 Dieta de recuperación · 🍚 Otro
//    Con un aviso de que estas dietas suelen ser indicadas por el
//    veterinario (lo son: son tratamientos, no tipos de comida).
//
// 3) VISIBILIDAD DEL DATO CLÍNICO — como la dieta especial es una
//    indicación veterinaria, NO se queda solo en el registro:
//    · CALENDARIO: el chip de "Lo alimentó" muestra las franjas
//      ("🥘 Lo alimentó (mañana, noche)") y aparece "🍚 Alimentación
//      especial (gastrointestinal)" en el día.
//    · /VET: bloque destacado "🍚 Alimentación especial" junto al
//      motivo de consulta, con el tipo, cuántos días se registró y la
//      fecha más reciente. Así el veterinario ve de un vistazo que la
//      mascota viene con dieta indicada, en vez de tener que buscarlo
//      entre los cuidados del día.
//
// VERIFICACIÓN NECESARIA: la vista /vet obtiene los registros con el
// RPC obtener_datos_veterinario. Si ese RPC selecciona columnas
// explícitas (en vez de SELECT *), habría que agregar
// alimentacion_especial a su SELECT para que el bloque del vet reciba
// el dato. Si usa SELECT * o el tipo completo de la tabla, ya funciona
// sin tocar nada. (El registro diario y el calendario no dependen del
// RPC, así que esos funcionan de todas formas.)
//
// Uso:
//   1) SQL primero: sql_275_alimentacion.sql → Run
//   2) node generar_275_alimentacion_franjas_y_especial.js
//   3) git add . && commit && push

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/registro-diario/page.tsx",
    base64: ""
  },
  {
    ruta: "app/calendario/page.tsx",
    base64: ""
  },
  {
    ruta: "app/vet/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 3 archivos escritos.')
  console.log('Recuerda: SQL primero, luego git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
